private fun af(key:String,label:String,type:String="text",value:Any?="",required:Boolean=false)=Field(key,label,type,value,required=required)
private fun JSONObject.v(key:String,default:Any=""):Any=opt(key)?.takeUnless{it==JSONObject.NULL}?:default
