 af("name","Nazwa węzła",value=r.v("name"),required=true),af("description","Opis","multiline",r.v("description")),af("fqdn","Adres FQDN",value=r.v("fqdn"),required=true),Field("scheme","Protokół","select",r.v("scheme","https"),mapOf("https" to "HTTPS","http" to "HTTP")),af("behind_proxy","Za reverse proxy","bool",r.optBoolean("behind_proxy")),af("public","Publiczny przydział","bool",r.optBoolean("public",true)),af("maintenance_mode","Tryb konserwacji","bool",r.optBoolean("maintenance_mode")),af("memory","Pamięć (MB)","integer",r.v("memory",8192)),af("memory_overallocate","Nadprzydział pamięci (%)","integer",r.v("memory_overallocate",0)),af("cpu","CPU węzła (%)","integer",r.v("cpu",800)),af("cpu_overallocate","Nadprzydział CPU (%)","integer",r.v("cpu_overallocate",0)),af("disk","Dysk (MB)","integer",r.v("disk",50000)),af("disk_overallocate","Nadprzydział dysku (%)","integer",r.v("disk_overallocate",0)),af("upload_size","Limit wysyłania (MB)","integer",r.v("upload_size",100)),af("daemon_listen","Port nasłuchiwania Wings","integer",r.v("daemon_listen",8080)),af("daemon_connect","Port połączenia z Wings","integer",r.v("daemon_connect",443)),af("daemon_sftp","Port SFTP","integer",r.v("daemon_sftp",2022)),af("daemon_base","Katalog danych",value=r.v("daemon_base","/var/lib/pelican/volumes")),af("tags","Tagi węzła (lista)","json",(r.optJSONArray("tags")?:JSONArray()).toString()))
