@Composable fun AdminResourceScreen(api:PelicanApi,spec:ResourceSpec,back:(()->Unit)?=null){ResourceList(api,spec,back)}
@Composable fun AdminOverview(api:PelicanApi,onSection:(Int)->Unit,onAccount:()->Unit){
 var stats by remember(api){mutableStateOf<Map<String,Int>>(emptyMap())};var errors by remember{mutableStateOf<List<String>>(emptyList())};var revision by remember{mutableIntStateOf(0)};var busy by remember{mutableStateOf(false)}
 LaunchedEffect(api,revision){busy=true;val result=linkedMapOf<String,Int>();val messages=mutableListOf<String>();for(path in listOf("servers","nodes","users")){try{val r=api.json("/$path?per_page=1",admin=true);result[path]=r.optJSONObject("meta")?.optJSONObject("pagination")?.optInt("total")?:r.objects().size}catch(e:Exception){messages+="${human(path)}: ${e.message}"}};stats=result;errors=messages;busy=false}
 Page("Administracja","Dostęp sprawdzany przez Pelicana",actions={IconButton(onClick={revision++}){Icon(Icons.Outlined.Refresh,"Odśwież administrację")}}){
  Hero("Twoja infrastruktura.","Użytkownicy, węzły i serwery Pelicana."){stats.forEach{(k,v)->Metric(human(k),v.toString())}}
  if(busy)LinearProgressIndicator(Modifier.fillMaxWidth())
  errors.forEach{ErrorCard(it)}
  if(stats.isEmpty()&&!busy)OutlinedButton(onClick=onAccount,modifier=Modifier.fillMaxWidth()){Text("Skonfiguruj dostęp administratora")}
  Shortcut("Serwery","Tworzenie, zasoby, blokady i transfery",Icons.Outlined.Dns){onSection(1)}
  Shortcut("Węzły Wings","Konfiguracja i przydziały portów",Icons.Outlined.Hub){onSection(2)}
  Shortcut("Użytkownicy","Konta, role i dostęp",Icons.Outlined.People){onSection(3)}
  Shortcut("Pozostałe zasoby","Dodatki, eggs, role i montowania",Icons.Outlined.Apps){onSection(4)}
 }
}
@Composable fun AdminMore(api:PelicanApi,onAccount:()->Unit){
 var resource by remember{mutableStateOf<ResourceSpec?>(null)};var settings by remember{mutableStateOf(false)}
 if(resource!=null){AdminResourceScreen(api,resource!!,{resource=null});return};if(settings){GlobalSettingsScreen(api,{settings=false});return}
 Page("Zasoby administracyjne","Natywna obsługa API administracyjnego"){
  listOf(AdminResources.plugins,AdminResources.eggs,AdminResources.roles,AdminResources.databaseHosts,AdminResources.mounts).forEach{r->Shortcut(r.title,"",Icons.Outlined.Extension){resource=r}}
  Shortcut("Ustawienia panelu","Nazwa, wygląd i strefa czasowa",Icons.Outlined.Settings){settings=true}
  Shortcut("Konto i klucze API","Połączenie z panelem",Icons.Outlined.AccountCircle,onAccount)
 }
}

@Composable fun GlobalSettingsScreen(api:PelicanApi,back:()->Unit){
 var fields by remember{mutableStateOf<List<Field>>(emptyList())};var error by remember{mutableStateOf("")};var ready by remember{mutableStateOf(false)}
 LaunchedEffect(api){try{fields=jsonFields(api.json("/mobile-control/settings",admin=true).getJSONArray("fields"));ready=true}catch(e:Exception){error=e.message.orEmpty()}}
 if(ready)OperationForm(Operation("Zapisz ustawienia panelu","/mobile-control/settings",fields=fields,admin=true),api,back,{back()})
 else Page("Ustawienia panelu",back=back){if(error.isNotBlank())ErrorCard(error)else LinearProgressIndicator(Modifier.fillMaxWidth())}
}
